import static net.runelite.api.widgets.WidgetPositionMode.ABSOLUTE_TOP;
import static net.runelite.api.widgets.WidgetSizeMode.ABSOLUTE;
import static net.runelite.api.widgets.WidgetSizeMode.MINUS;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;
import org.apache.commons.lang3.tuple.Pair;

/**
 * <ul>
 *     <li>Removes channel name from chat widgets</li>
 *     <li>Indents multi-line messages</li>
 *     <li>Adjusts message height based on name removal and indentation</li>
 * </ul>
 */
@Slf4j
@Singleton
public class ChatWidgetEditor
{
	@Inject
	private ImprovedChatConfig config;

	@Inject
	private ChannelNameManager channelNameManager;

	@Inject
	private Client client;

	@Inject
	private CleanChatModule plugin;

	private boolean anyChatCleanupEnabled()
	{
		return config.removeWelcome()
			|| config.indentationMode() != com.improvedchat.chatbox.clean.data.IndentMode.MESSAGE
			|| config.hideScrollbar()
			|| config.hideSpecs()
			|| config.isFixedWidthTimestampEnabled()
			|| config.isColorBarEnabled()
			|| config.removeClanInstruction()
			|| config.removeClanName()
			|| config.removeClanRank()
			|| config.removeGuestClanInstruction()
			|| config.removeGuestClanReconnecting()
			|| config.removeGuestClanName()
			|| config.removeGroupIronInstruction()
			|| config.removeGroupIronName()
			|| config.removeGroupIronFromClan()
			|| config.removeFriendsChatStartup()
			|| config.removeFriendsChatName()
			|| config.removeFriendsAttempting()
			|| config.removeFriendsNowTalking()
			|| !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortClanName())
			|| !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortGuestClanName())
			|| !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortGroupIronName())
			|| !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortFriendsName());
	}

	private int lastScrollDiff = -1;
	private int lastChatTab = ChatTab.CLOSED.getValue();
	private boolean chatboxScrolled = false;

	@Getter
	public List<ChatWidgetGroup> chatWidgetGroups = List.of();

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// Reset scroll
			lastScrollDiff = -1;
			chatboxScrolled = false;
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (!anyChatCleanupEnabled())
		{
			return;
		}

		if (event.getScriptId() >= SCRIPT_SCROLLBAR_MIN && event.getScriptId() <= SCRIPT_SCROLLBAR_MAX && event.getScriptEvent() != null)
		{
			Object[] args = event.getScriptEvent().getArguments();
			chatboxScrolled = args.length >= 2 && (int) args[1] == InterfaceID.Chatbox.CHATSCROLLBAR;
		}
	}

	/*
	Most chats appear in this format as dynamic children on the chatbox scroll area:
		// bottom chat line
		[0] = username
		[1] = chat message
		[2] = timestamp + channel name (timestamp only if that plugin is on, but is pretty common so should definitely account for it)
		[3] = rank icon
		// Next chat line
		[4] = next username
		etc...

	However, some are special:

	Friends chats:
		[0] = channel + username
		[1] = chat message
		[2] = nothing
		[3] = rank icon

	Friends game messages:
		[0] = timestamp + message
		[1] = nothing (except for the 'now talking...' message specifically which has the CLAN chat join message here...)
		[2] = nothing
		[3] = nothing

	GIM broadcasts:
		[0] = channel
		[1] = chat message
		[2] = nothing
		[3] = nothing

	Console message:
		[0] = timestamp + message
		[1] = nothing
		[2] = nothing
		[3] = nothing

	GIM or Clan broadcast after world hopping (before you have reconnected to the channel):
		[0] = nothing
		[1] = message
		[2] = nothing
		[3] = nothing

	Clan instruction message (?) after world hopping:
		[0] = message
		[1] = Did you know? tip
		[2] = nothing
		[3] = nothing

	These appear in the children array in this order even if the individual items aren't rendered
	 ex: Username is hidden for broadcasts, rank icon is hidden for public chat */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (!anyChatCleanupEnabled())
		{
			chatWidgetGroups = List.of();
			return;
		}

		if (event.getScriptId() == SCRIPT_REBUILD_CHATBOX)
		{
			checkReplacements();
		}
		else if (event.getScriptId() >= SCRIPT_SCROLLBAR_MIN && event.getScriptId() <= SCRIPT_SCROLLBAR_MAX && chatboxScrolled)
		{
			chatboxScrolled = false;

			Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
			if (chatbox != null)
			{
				lastScrollDiff = chatbox.getScrollHeight() - chatbox.getScrollY();
				client.setVarcIntValue(VarClientID.CHAT_LASTSCROLLPOS, chatbox.getScrollHeight() - lastScrollDiff);
			}
		}
	}

	public void checkReplacements()
	{
		if (!anyChatCleanupEnabled())
		{
			chatWidgetGroups = List.of();
			return;
		}

		// FriendsChatManager is null at the first FriendsChatChanged after login so we have to add this check later
		channelNameManager.updateFriendsChatName();

		Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		ChatTab selectedChatTab = ChatTab.of(client.getVarcIntValue(VarClientID.CHAT_VIEW));

		if (chatbox != null && selectedChatTab != ChatTab.CLOSED)
		{
			Widget[] chatWidgets = chatbox.getDynamicChildren().clone();
			Widget[] clickboxWidgets = chatbox.getStaticChildren().clone();

			// TODO: See if we can avoid looping through every single widget even if there is no text there
			// for (int i = 0; i < chats.length; i += 4)
			chatWidgetGroups = Stream.iterate(
					0,
					i -> i < chatWidgets.length,
					i -> i + 4
				)
				.map(i -> {
					int rankWidgetIndex = i + 3;
					int messageWidgetIndex = i + 1;
					int nameWidgetIndex = i;

					Widget channelWidget = chatWidgets[i + 2];
					if (channelWidget.getText().isEmpty())
					{
						// Channel is not at [2]. This is either a message with channel at [0] or a message without a channel

						if (!chatWidgets[i].getText().isEmpty())
						{
							// Channel is at [0], this is a special message, adjust indices accordingly

							Widget messageWidget = chatWidgets[i + 1];
							// For some reason the fc now talking message specifically, has the CLAN chat join message here...
							if (messageWidget.getText().isEmpty() || Text.removeTags(messageWidget.getText()).equals(CLAN_INSTRUCTION_MESSAGE))
							{
								// Friends chat message

								messageWidgetIndex = i;
								// Empty widget in this case, but still good to handle it
								nameWidgetIndex = i + 1;
							}
							else
							{
								// Other special message

								channelWidget = chatWidgets[i];
								// Empty widget in this case, but still good to handle it
								nameWidgetIndex = i + 2;
							}
						}
						else if (chatWidgets[messageWidgetIndex].getText().isEmpty())
						{
							return null;
						}
						else
						{
							// Clan/GIM broadcast after world hopping - just use default setup since we mainly care about the message in this case
						}
					}

					return new ChatWidgetGroup(channelWidget, chatWidgets[rankWidgetIndex], chatWidgets[nameWidgetIndex], chatWidgets[messageWidgetIndex], clickboxWidgets[i / 4]);
				})
				.filter(Objects::nonNull)
				.peek(group -> {
					if (!group.getChannelText().isEmpty())
					{
						Pair<ChatChannel, String> match = ChatChannel.findChannelMatch(group.getChannelText(), channelNameManager);
						if (match != null)
						{
							ChatChannel channel = match.getLeft();
							String matchedChannelName = match.getRight();
							String widgetChannelText = sanitizeName(group.getChannelText());
							String shortName = channel.getShortName(channelNameManager, matchedChannelName);

							group.setChannelType(channel);

							if (channel.isChannelNameRemovalEnabled(config))
							{
								group.removeFromChannel(matchedChannelName, client);

								matchedChannelName = wrapWithBrackets(matchedChannelName);
							}
							else if (!shortName.isBlank() && !channel.isShortNameDefault(channelNameManager))
							{
								String updatedChannelText = group.replaceChannelName(matchedChannelName, shortName, client);

								matchedChannelName = sanitizeName(shortName);
								widgetChannelText = sanitizeName(updatedChannelText);
							}
							else
							{
								matchedChannelName = wrapWithBrackets(matchedChannelName);
							}

							if (channel.isRemoveRankEnabled(config))
							{
								group.removeRank();
							}

							if (channel != ChatChannel.FRIENDS_CHAT)
							{
								group.calculateChannelIndent(config, matchedChannelName, widgetChannelText,
									plugin.getTimestampTemplateWidth(), plugin.isFixedWidthTimestampEnabled(), client);
							}
						}
					}

					if (plugin.isFixedWidthTimestampEnabled())
					{
						group.extractTimestamp(plugin.getTimestampTemplate(), plugin.getTimestampTemplateWidth(), client);
					}

					group.applyIndent();

					// Calculate height last
					group.calculateHeight(client);
				})
				.collect(Collectors.toList());

			Collections.reverse(chatWidgetGroups);

			// Calculate this after editing messages
			int totalHeight = chatWidgetGroups.stream()
				.map(ChatWidgetGroup::getHeight)
				.reduce(0, Integer::sum);

			// If we only have a few messages we want to place them at the bottom (chatbox.getHeight()) instead of the top (0).
			//  If placing from the bottom, add padding first
			int y = totalHeight >= chatbox.getHeight() ? 0 : chatbox.getHeight() - totalHeight - 2;

			// Place widgets vertically
			for (ChatWidgetGroup group : chatWidgetGroups)
			{
				group.place(y);

				y += group.getHeight();
			}

			// If placing at the top, add padding last
			if (totalHeight >= chatbox.getHeight())
			{
				y += 2;
			}

			y = max(y, chatbox.getHeight());

			chatbox.setScrollHeight(y);
			chatbox.revalidateScroll();

			// Replacing this script with Java allows us to avoid a clientThread.invokeLater as well as adjust the logic since we are modifying the true scroll height
			scrollbar_resize(chatbox);

			// Store this since rebuildchatbox changes the scroll position before we can
			lastScrollDiff = chatbox.getScrollHeight() - chatbox.getScrollY();
		}
		else
		{
			// chat closed - reset scroll
			lastScrollDiff = -1;
			chatboxScrolled = false;
		}
		lastChatTab = selectedChatTab.getValue();
	}

	// Script 72
	private void scrollbar_resize(Widget scrollArea)
	{
		Widget scrollBarContainer = client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR);

		int scrollAreaHeight = scrollArea.getScrollHeight();
		if (scrollAreaHeight <= 0)
		{
			scrollAreaHeight = scrollArea.getHeight();
		}

		int scrollBarHeight;
		if (scrollAreaHeight > 0)
		{
			scrollBarHeight = (scrollBarContainer.getHeight() - 32) * scrollArea.getHeight() / scrollAreaHeight;
		}
		else
		{
			scrollBarHeight = scrollBarContainer.getHeight() - 32;
		}
		if (scrollBarHeight < 10)
		{
			scrollBarHeight = 10;
		}

		Widget scrollBar = scrollBarContainer.getChild(1);
		if (scrollBar != null)
		{
			scrollBar.setSize(0, scrollBarHeight, MINUS, ABSOLUTE);
			scrollBar.revalidate();

			scrollbar_vertical_doscroll(scrollBarContainer, scrollArea, scrollBar);

			scrollBarContainer.revalidateScroll();
			scrollArea.revalidateScroll();
		}
	}

	// Script 37
	private void scrollbar_vertical_doscroll(Widget scrollBarContainer, Widget scrollArea, Widget scrollBar)
	{
		int int2;
		if (lastChatTab != ChatTab.CLOSED.getValue() && lastScrollDiff != -1)
		{
			// Custom logic to restore our scroll values since rebuildchatbox will override them
			int2 = max(scrollArea.getScrollHeight() - lastScrollDiff, 0);
		}
		else if (scrollArea.getHeight() < 0)
		{
			// For some reason scrollArea.getHeight is negative after the first login so we just default to 0
			int2 = 0;
			// The scrollHeight is also wrong after first login so just default to the base height
			scrollArea.setScrollHeight(114);
		}
		else
		{
			// Original script logic
			int2 = scrollArea.getScrollY();
			int int3 = max(scrollArea.getScrollHeight() - scrollArea.getHeight(), 1);
			int2 = max(min(int2, int3), 0);
		}
		scrollArea.setScrollY(int2);
		scrollArea.revalidateScroll();
		client.setVarcIntValue(VarClientID.CHAT_LASTSCROLLPOS, scrollArea.getScrollY());

		scrollbar_vertical_setdragger(scrollBarContainer, scrollArea, scrollBar);
	}

	// Script 740
	private void scrollbar_vertical_setdragger(Widget scrollBarContainer, Widget scrollArea, Widget scrollBar)
	{
		int int2 = max(scrollArea.getScrollHeight() - scrollArea.getHeight(), 1);
		int int3 = scrollBarContainer.getHeight() - 32 - scrollBar.getHeight();

		int scrollBarPos = max(16 + int3 * scrollArea.getScrollY() / int2, 16);
		scrollBar.setPos(0, scrollBarPos, ABSOLUTE_CENTER, ABSOLUTE_TOP);
		scrollBar.revalidate();

		Widget scrollbarElementTop = scrollBarContainer.getChild(2);
		if (scrollbarElementTop != null)
		{
			scrollbarElementTop.setPos(0, scrollBar.getOriginalY(), ABSOLUTE_CENTER, ABSOLUTE_TOP);
			scrollbarElementTop.revalidate();
		}

		Widget scrollbarElementBottom = scrollBarContainer.getChild(3);
		if (scrollbarElementBottom != null)
		{
			scrollbarElementBottom.setPos(0, scrollBar.getOriginalY() + scrollBar.getHeight() - 5, ABSOLUTE_CENTER, ABSOLUTE_TOP);
			scrollbarElementBottom.revalidate();
		}
	}

}

package com.improvedchat.chatbox.clean;

import com.improvedchat.ImprovedChatConfig;
import static com.improvedchat.chatbox.clean.util.CleanChatUtil.getTextLength;
import static com.improvedchat.chatbox.clean.util.CleanChatUtil.getTextLineCount;
import static com.improvedchat.chatbox.clean.util.CleanChatUtil.wrapWithBrackets;
import static com.improvedchat.chatbox.clean.util.CleanChatUtil.wrapWithChannelNameRegex;
import com.improvedchat.chatbox.clean.data.ChatChannel;
import com.improvedchat.chatbox.clean.util.FormatterExtractor;
import java.awt.Color;
import static java.lang.Math.max;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.NonNull;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

@Slf4j
@RequiredArgsConstructor
public class ChatWidgetGroup
{
	@NonNull
	private final Widget channel;
	@NonNull
	private final Widget rank;
	@NonNull
	private final Widget name;
	@NonNull
	private final Widget message;
	@NonNull
	private final Widget clickBox;

	@Setter
	@Nullable
	private ChatChannel channelType = null;

	private int messageIndentSpaces = 0;
	private int timestampX = -1;

	@Getter
	@Nullable
	private FormatterExtractor.ExtractionResult timestamp = null;

	public String getChannelText()
	{
		return channel.getText();
	}

	public int getHeight()
	{
		return message.getHeight();
	}

	public int getY()
	{
		if (channel.isHidden())
		{
			return message.getCanvasLocation().getY();
		}
		return channel.getCanvasLocation().getY();
	}

	public int getX()
	{
		if (channel.isHidden())
		{
			return message.getCanvasLocation().getX();
		}
		return channel.getCanvasLocation().getX();
	}

	public Color getColor(ImprovedChatConfig config)
	{
		return channelType != null ? channelType.getColor(config) : config.noChannelColor();
	}

	public int getTimestampX()
	{
		return timestampX >= 0 ? timestampX : getX();
	}

	public void place(final int y)
	{
		place(channel, y);
		place(rank, y);
		place(name, y);
		place(message, y);

		clickBox.setOriginalY(y);
		clickBox.setHidden(false);
		clickBox.revalidate();
	}

	public void calculateHeight(Client client)
	{
		if (!message.getText().isEmpty() && message.getWidth() > 0)
		{
			int numLines = getTextLineCount(message.getText(), message.getWidth(), messageIndentSpaces, client);
			int height = numLines * 14; // Height of each line is always 14
			message.setOriginalHeight(height);
			message.revalidate();

			clickBox.setOriginalHeight(height);
			clickBox.revalidate();
		}
	}

	public void calculateChannelIndent(ImprovedChatConfig config, String matchedChannelName, String widgetChannelText,
									   int timestampWidth, boolean isFixedWidthTimestampEnabled, Client client)
	{
		if (channelType == ChatChannel.FRIENDS_CHAT)
		{
			// For some reason the fc channel width is the entire length of the chatbox so to make things easier we adjust that here
			channel.setOriginalWidth(message.getOriginalX() - channel.getOriginalX());
			channel.revalidate();
		}

		int startOfChannel = widgetChannelText.indexOf(matchedChannelName);
		int endOfChannel = startOfChannel + matchedChannelName.length();

		int indentWidth = 0;

		int channelWidth = 0;
		int prefixWidth = 0;

		// TODO: See if there's something that we are missing when measuring so we can avoid adding all these hardcoded offsets
		if (channelType != null)
		{
			switch (config.indentationMode())
			{
				// Intentionally fallthrough
				case START:
					// extractTimestamp handles indents for start already
					if (isFixedWidthTimestampEnabled)
					{
						// Fixed-width timestamps reserve an exact pixel slot. Wrapped-line
						// indentation must use that slot width rather than the variable width of
						// the timestamp text that happened to be rendered on this message.
						prefixWidth = timestampWidth;
						indentWidth += prefixWidth;

						if (channelType.isChannelNameRemovalEnabled(config))
						{
							if (channelType == ChatChannel.FRIENDS_CHAT)
							{
								indentWidth += 1;
							}
							else
							{
								indentWidth -= 2;
							}
						}
					}
				case CHANNEL:
					if (!channelType.isChannelNameRemovalEnabled(config))
					{
						String channel = widgetChannelText.substring(startOfChannel, endOfChannel);
						channelWidth = getTextLength(channel, client);
						indentWidth += channelWidth;

						if (channelType != ChatChannel.FRIENDS_CHAT)
						{
							indentWidth += 1;
						}
						else
						{
							indentWidth += 4;
						}
					}
				case NAME:
					int nameWidth = 0;
					// FC puts name + channel into the channel widget
					if (channelType == ChatChannel.FRIENDS_CHAT)
					{
						if (isFixedWidthTimestampEnabled)
						{
							nameWidth = (channel.getWidth() - timestampWidth) - channelWidth;
						}
						else
						{
							nameWidth = channel.getWidth() - prefixWidth - channelWidth;
						}
					}
					else
					{
						if (!name.getText().isEmpty() && !name.isHidden())
						{
							nameWidth = name.getWidth();
						}
					}

					if (!rank.isHidden())
					{
						nameWidth += rank.getWidth();
					}

					indentWidth += nameWidth;

					if (indentWidth > 0 && channelType != ChatChannel.FRIENDS_CHAT)
					{
						indentWidth += 4;
					}
					else if (channelType == ChatChannel.FRIENDS_CHAT)
					{
						indentWidth -= 4;
					}
				case MESSAGE:
					// Already set by default
			}
		}

		if (indentWidth > 0)
		{
			messageIndentSpaces += max(0, indentWidth / 3);

			if (messageIndentSpaces > 0)
			{
				message.setOriginalX(message.getOriginalX() - indentWidth);
				message.setOriginalWidth(message.getOriginalWidth() + indentWidth);
				message.revalidate();
			}
		}
	}

	public void applyIndent()
	{
		if (messageIndentSpaces > 0)
		{
			// Indentation mode still uses native text spacing for wrapped-message indentation.
			// Fixed-width timestamps no longer participate in this approximation; they own a real
			// pixel slot in extractTimestamp/applyFixedTimestampSlot.
			message.setText(" ".repeat(messageIndentSpaces) + message.getText());
			message.revalidate();
		}
	}

	public void removeFromChannel(String text, Client client)
	{
		replaceChannelName(text, "", client);
	}

	public String replaceChannelName(String text, String newChannelName, Client client)
	{
		int currentWidth = getTextLength(wrapWithBrackets(text), client);
		int newWidth = getTextLength(newChannelName, client);
		int removedWidth = currentWidth - newWidth;

		String newText = channel.getText()
			// TODO: Target the channel name more precisely, this should do for now to avoid targeting timestamps in brackets
			.replaceFirst(wrapWithChannelNameRegex(text), newChannelName);

		// Remove trailing spaces - probably only happens with timestamps turned on
		if (newText.endsWith(" "))
		{
			newText = newText.substring(0, newText.length() - 1);
			removedWidth += getTextLength(" ", client);
		}

		// Remove double spaces - mainly found in friends chat since it has sender + username
		if (newText.contains("  "))
		{
			newText = newText.replaceFirst(" {2}", " ");
			removedWidth += getTextLength(" ", client);
		}

		channel.setText(newText);

		// Shift widgets X left if channel was removed
		shiftLeft(rank, removedWidth);
		shiftLeft(name, removedWidth);
		shiftLeft(message, removedWidth);

		// Expand the width of messages if channel was removed
		message.setOriginalWidth(message.getOriginalWidth() + removedWidth);
		message.revalidate();

		// Reduce channel width if it was removed
		channel.setOriginalWidth(channel.getOriginalWidth() - removedWidth);
		channel.revalidate();

		return newText;
	}

	public void removeRank()
	{
		if (!rank.isHidden())
		{
			rank.setHidden(true);

			int removedWidth = rank.getWidth();

			shiftLeft(name, removedWidth);
			shiftLeft(message, removedWidth);

			// Expand the width of messages if rank was removed
			expand(message, removedWidth);
		}
	}

	private void shiftLeft(Widget widget, int width)
	{
		widget.setOriginalX(widget.getOriginalX() - width);
		widget.revalidate();
	}

	private void expand(Widget widget, int width)
	{
		widget.setOriginalWidth(widget.getOriginalWidth() + width);
		widget.revalidate();
	}

	private void place(Widget widget, int y)
	{
		widget.setOriginalY(y);
		widget.revalidate();
	}

	public void extractTimestamp(FormatterExtractor.ExtractionResult template, int timestampWidth, Client client)
	{
		if (template == null)
		{
			timestamp = null;
			timestampX = -1;
			return;
		}

		Widget widget;
		Widget oppositeWidget;

		if (!message.getText().isEmpty())
		{
			widget = message;
			oppositeWidget = channel;
		}
		else
		{
			widget = channel;
			oppositeWidget = message;
		}

		timestamp = FormatterExtractor.extractFromText(template, widget.getText());

		if (timestamp == null)
		{
			timestamp = FormatterExtractor.extractFromText(template, oppositeWidget.getText());

			if (timestamp == null)
			{
				timestampX = -1;
				log.debug("Timestamp could not be extracted from template: `{}`, widget:`{}`, or opposite widget:`{}`", template, widget.getText(), oppositeWidget.getText());
				return;
			}
			widget = oppositeWidget;
		}

		timestampX = widget.getCanvasLocation().getX();
		int actualTimestampWidth = getTextLength(timestamp.getFormattedOutput(), client);
		applyFixedTimestampSlot(widget, timestamp.getRemainingText(), actualTimestampWidth, timestampWidth, client);
	}

	private void applyFixedTimestampSlot(Widget timestampWidget, String remainingText,
		int actualTimestampWidth, int targetTimestampWidth, Client client)
	{
		int spaceWidth = max(1, getTextLength(" ", client));
		int targetWidth = max(0, targetTimestampWidth);
		int actualWidth = max(0, actualTimestampWidth);

		// The fixed timestamp renderer draws over an exact-width run of native chat spaces.
		// Keeping the timestamp-bearing widget at its RuneLite-provided X coordinate is critical:
		// moving that widget moves the timestamp itself and any overlays anchored to the chat line.
		int paddingSpaces = (targetWidth + spaceWidth - 1) / spaceWidth;
		targetWidth = paddingSpaces * spaceWidth;
		timestampWidget.setText(" ".repeat(paddingSpaces) + remainingText);
		timestampWidget.revalidate();

		int delta = targetWidth - actualWidth;
		if (timestampWidget == channel)
		{
			// Normal player/channel lines keep the timestamp and any remaining channel text in the
			// channel widget. Grow/shrink that widget by only the width difference, then move the
			// separate rank, sender, and message widgets by the same delta. The timestamp origin
			// itself never moves.
			channel.setOriginalWidth(max(0, channel.getOriginalWidth() + delta));
			channel.revalidate();

			shiftX(rank, delta);
			shiftX(name, delta);
			shiftXPreserveRight(message, delta);
		}
		// Game/system lines keep timestamp and body in one message widget. The exact-width space
		// prefix reserves the slot without changing widget geometry, so the body naturally begins
		// after the timestamp while the right edge and wrapping area remain RuneLite-native.
	}

	private void shiftX(Widget widget, int amount)
	{
		if (amount == 0)
		{
			return;
		}
		widget.setOriginalX(widget.getOriginalX() + amount);
		widget.revalidate();
	}

	private void shiftXPreserveRight(Widget widget, int amount)
	{
		if (amount == 0)
		{
			return;
		}
		widget.setOriginalX(widget.getOriginalX() + amount);
		widget.setOriginalWidth(max(0, widget.getOriginalWidth() - amount));
		widget.revalidate();
	}

	@Override
	public String toString()
	{
		return "ChatWidgetGroup{" + ",\n" +
			"channel=" + channel.getText() + ",\n" +
			"rank=" + rank.getSpriteId() + ",\n" +
			"name=" + name.getText() + ",\n" +
			"message=" + message.getText() + ",\n" +
			"channelType=" + (channelType != null ? channel.getName() : null) + ",\n" +
			"timestamp=" + (timestamp != null ? timestamp.getFormattedOutput() : null) + "\n" +
			'}';
	}
}

package com.improvedchat.chatbox.clean;

import com.improvedchat.ImprovedChatConfig;
import com.improvedchat.chatbox.clean.overlay.ChatColorBarOverlay;
import com.improvedchat.chatbox.clean.overlay.ChatTimestampOverlay;
import com.improvedchat.chatbox.clean.util.FormatterExtractor;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.timestamp.TimestampPlugin;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Lifecycle for Improved Chat's native message and layout cleanup features.
 * Individual cleanup settings can be enabled independently.
 */
@Singleton
public final class CleanChatModule {
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ImprovedChatConfig config;
    @Inject private ChannelNameManager channelNameManager;
    @Inject private ChatWidgetEditor chatWidgetEditor;
    @Inject private ChatBlocker chatBlocker;
    @Inject private EventBus eventBus;
    @Inject private OverlayManager overlayManager;
    @Inject private PluginManager pluginManager;
    @Inject private ChatColorBarOverlay colorBarOverlay;
    @Inject private ChatTimestampOverlay timestampOverlay;

    private boolean started;
    private boolean timestampPluginEnabled;
    private FormatterExtractor.ExtractionResult timestampTemplate;
    private int timestampTemplateWidth;

    public synchronized void startUp() {
        if (started) {
            return;
        }
        started = true;
        timestampPluginEnabled = findTimestampPluginEnabled();

        eventBus.register(this);
        eventBus.register(chatBlocker);
        eventBus.register(chatWidgetEditor);
        eventBus.register(channelNameManager);
        channelNameManager.startup();

        eventBus.register(timestampOverlay);
        overlayManager.add(timestampOverlay);
        timestampOverlay.startUp();
        overlayManager.add(colorBarOverlay);

        clientThread.invoke(() -> {
            if (config.hideScrollbar()) {
                handleScrollbarVisibility(true);
            }
            if (client.getGameState() == GameState.LOGGED_IN && hasActiveCleanupSettings(config)) {
                client.refreshChat();
            }
        });
    }

    public synchronized void shutDown() {
        if (!started) {
            return;
        }
        started = false;

        eventBus.unregister(chatBlocker);
        eventBus.unregister(chatWidgetEditor);
        eventBus.unregister(channelNameManager);
        eventBus.unregister(timestampOverlay);
        eventBus.unregister(this);

        overlayManager.remove(timestampOverlay);
        overlayManager.remove(colorBarOverlay);
        channelNameManager.shutdown();

        clientThread.invoke(() -> {
            if (config.hideScrollbar()) {
                handleScrollbarVisibility(false);
            }
            if (client.getGameState() == GameState.LOGGED_IN && hasActiveCleanupSettings(config)) {
                client.refreshChat();
            }
        });
    }

    public boolean isFixedWidthTimestampEnabled() {
        return started && config.isFixedWidthTimestampEnabled() && timestampPluginEnabled;
    }

    public FormatterExtractor.ExtractionResult getTimestampTemplate() {
        return timestampTemplate;
    }

    public void setTimestampTemplate(FormatterExtractor.ExtractionResult timestampTemplate) {
        this.timestampTemplate = timestampTemplate;
    }

    public int getTimestampTemplateWidth() {
        return timestampTemplateWidth;
    }

    public void setTimestampTemplateWidth(int timestampTemplateWidth) {
        this.timestampTemplateWidth = timestampTemplateWidth;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (ImprovedChatConfig.GROUP.equals(event.getGroup())) {
            if (!started || !isCleanupConfigKey(event.getKey())) {
                return;
            }
            clientThread.invokeLater(() -> {
                if (ImprovedChatConfig.HIDE_SCROLLBAR_KEY.equals(event.getKey())) {
                    handleScrollbarVisibility(config.hideScrollbar());
                }
                client.refreshChat();
            });
            return;
        }

        if ("runelite".equals(event.getGroup()) && "timestampplugin".equals(event.getKey())) {
            timestampPluginEnabled = findTimestampPluginEnabled();
            clientThread.invokeLater(client::refreshChat);
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        if (started && event.getGroupId() == InterfaceID.CHATBOX) {
            handleScrollbarVisibility(config.hideScrollbar());
        }
    }

    private static boolean isCleanupConfigKey(String key) {
        if (key == null) {
            return false;
        }

        switch (key) {
            case "removeWelcome":
            case "lineBreakIndentationMode":
            case ImprovedChatConfig.HIDE_SCROLLBAR_KEY:
            case "hideSpecs":
            case "improvedTimestamps":
            case "colorBar":
            case "colorBarOffset":
            case "colorBarWidth":
            case "noChannelColor":
            case "clanColor":
            case "friendColor":
            case "groupIronColor":
            case "guestClanColor":
            case "removeClanInstruction":
            case "removeClanName":
            case "shortClanName":
            case "removeClanRank":
            case "removeGuestClanInstruction":
            case "removeGuestClanReconnecting":
            case "removeGuestClanName":
            case "shortGuestClanName":
            case "removeGroupIronInstruction":
            case "removeGroupIronName":
            case "moveGroupIronBroadcasts":
            case "shortGroupIronName":
            case "removeFriendsChatInstruction":
            case "removeFriendsChatName":
            case "removeFriendsAttempting":
            case "removeFriendsNowTalking":
            case "shortFriendsName":
                return true;
            default:
                return false;
        }
    }

    static boolean hasActiveCleanupSettings(ImprovedChatConfig config) {
        return config.removeWelcome()
            || config.indentationMode() != com.improvedchat.chatbox.clean.data.IndentMode.MESSAGE
            || config.hideScrollbar()
            || config.hideSpecs()
            || config.isFixedWidthTimestampEnabled()
            || config.isColorBarEnabled()
            || config.removeClanInstruction()
            || config.removeClanName()
            || config.removeClanRank()
            || config.removeGuestClanInstruction()
            || config.removeGuestClanReconnecting()
            || config.removeGuestClanName()
            || config.removeGroupIronInstruction()
            || config.removeGroupIronName()
            || config.removeGroupIronFromClan()
            || config.removeFriendsChatStartup()
            || config.removeFriendsChatName()
            || config.removeFriendsAttempting()
            || config.removeFriendsNowTalking()
            || !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortClanName())
            || !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortGuestClanName())
            || !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortGroupIronName())
            || !ImprovedChatConfig.DEFAULT_CUSTOM_CHANNEL_NAME.equals(config.getShortFriendsName());
    }

    private boolean findTimestampPluginEnabled() {
        for (Plugin plugin : pluginManager.getPlugins()) {
            if (plugin instanceof TimestampPlugin) {
                return pluginManager.isPluginEnabled(plugin);
            }
        }
        return false;
    }

    private void handleScrollbarVisibility(boolean hide) {
        Widget scrollArea = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        Widget scrollBar = client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR);
        if (scrollArea == null || scrollBar == null) {
            return;
        }

        scrollBar.setHidden(hide);
        // Width mode is MINUS; 0 consumes the full available parent width.
        scrollArea.setOriginalWidth(hide ? 0 : scrollBar.getWidth());
        scrollArea.revalidate();
    }
}

