package com.improvedchat.chatbox.clean.overlay;

import com.improvedchat.chatbox.clean.ChatWidgetEditor;
import com.improvedchat.chatbox.clean.ChatWidgetGroup;
import com.improvedchat.ImprovedChatConfig;
import com.improvedchat.chatbox.clean.data.ChatTab;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Abstract overlay that renders on each chat message and is clipped to the chatbox
 */
@Slf4j
public abstract class BaseCleanChatOverlay extends Overlay
{
	@Inject
	protected Client client;

	@Inject
	protected ChatWidgetEditor chatWidgetEditor;

	@Inject
	protected ImprovedChatConfig config;

	abstract boolean isEnabled();

	BaseCleanChatOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);

		drawAfterInterface(InterfaceID.CHATBOX);
	}

	@Override
	final public Dimension render(Graphics2D graphics)
	{
		if (!isEnabled())
		{
			return null;
		}

		Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		ChatTab selectedChatTab = ChatTab.of(client.getVarcIntValue(VarClientID.CHAT_VIEW));

		if (chatbox == null || chatbox.isHidden() || selectedChatTab == ChatTab.CLOSED)
		{
			return null;
		}

		graphics.setClip(chatbox.getCanvasLocation().getX(), chatbox.getCanvasLocation().getY(), chatbox.getWidth(), chatbox.getHeight());

		List<ChatWidgetGroup> allChats = List.copyOf(chatWidgetEditor.getChatWidgetGroups());
		if (allChats.isEmpty())
		{
			return null;
		}

		List<ChatWidgetGroup> visibleChats = new ArrayList<>();
		ChatWidgetGroup previousGroup = null;
		boolean foundStart = false;

		for (ChatWidgetGroup group : allChats)
		{
			boolean isVisibleInChat = group.getY() >= chatbox.getCanvasLocation().getY() &&
				group.getY() + group.getHeight() <= chatbox.getCanvasLocation().getY() + chatbox.getHeight();

			if (isVisibleInChat)
			{
				visibleChats.add(group);

				if (!foundStart)
				{
					foundStart = true;
					if (previousGroup != null)
					{
						// Element before first fully visible element
						visibleChats.add(0, previousGroup);
					}
				}
			}
			else if (foundStart)
			{
				// Element after last fully visible element
				visibleChats.add(group);
				break;
			}

			previousGroup = group;
		}

		visibleChats.forEach(group -> {
			int x = group.getX();
			int y = group.getY();

			render(graphics, x, y, group);
		});

		return null;
	}

	/**
	 * Called on each visible chat message
	 */
	abstract void render(Graphics2D graphics, int x, int y, ChatWidgetGroup group);
}

package com.improvedchat.chatbox.clean.overlay;

import com.improvedchat.chatbox.clean.ChatWidgetGroup;
import java.awt.Graphics2D;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

@Slf4j
@Singleton
public class ChatColorBarOverlay extends BaseCleanChatOverlay
{

	@Override
	void render(Graphics2D graphics, int x, int y, ChatWidgetGroup group)
	{
		Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);

		x = Math.min(
			Math.max(
				x + config.colorBarOffset(),
				chatbox != null ? chatbox.getCanvasLocation().getX() : 0
			),
			chatbox != null ? chatbox.getCanvasLocation().getX() + chatbox.getWidth() - 1 : 0
		);

		graphics.setColor(group.getColor(config));
		graphics.fillRect(x, y, config.colorBarWidth(), 16);
	}

	@Override
	boolean isEnabled()
	{
		return config.isColorBarEnabled();
	}
}

package com.improvedchat.chatbox.clean.overlay;

import com.improvedchat.chatbox.clean.ChatWidgetGroup;
import com.improvedchat.chatbox.clean.CleanChatModule;
import static com.improvedchat.chatbox.clean.util.CleanChatUtil.getTextLength;
import com.improvedchat.chatbox.clean.util.FormatterExtractor;
import java.awt.Color;
import java.awt.Graphics2D;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.timestamp.TimestampConfig;
import net.runelite.client.ui.FontManager;

@Slf4j
@Singleton
public class ChatTimestampOverlay extends BaseCleanChatOverlay
{
	private static final int NUMERIC_CELL_WIDTH = 8;
	private static final int TEXT_CELL_WIDTH = 9;

	@Inject
	private ConfigManager configManager;

	@Inject
	private CleanChatModule plugin;

	@Inject
	private Client client;

	@Override
	boolean isEnabled()
	{
		return plugin.isFixedWidthTimestampEnabled();
	}

	@Override
	void render(Graphics2D graphics, int x, int y, ChatWidgetGroup group)
	{
		FormatterExtractor.ExtractionResult timestamp = group.getTimestamp();

		if (timestamp == null)
		{
			return;
		}

		int timestampY = y + 14;

		Color timestampColor = getTimestampColour();
		graphics.setColor(timestampColor);

		graphics.setFont(FontManager.getRunescapeFont());

		AtomicInteger timestampX = new AtomicInteger(group.getTimestampX());

		boolean isChatboxTransparent = client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) == 1;

		FormatterExtractor.iterateOutputParts(timestamp, new FormatterExtractor.OutputPartConsumer()
		{
			@Override
			public void consumeSegment(FormatterExtractor.FormatSegment segment)
			{
				String value = segment.value == null ? "" : segment.value;
				int cellWidth = cellWidth(segment);
				for (int i = 0; i < value.length(); i++)
				{
					String str = String.valueOf(value.charAt(i));

					if (isChatboxTransparent)
					{
						// Draw shadow
						graphics.setColor(Color.BLACK);
						graphics.drawString(str, timestampX.get() + 1, timestampY + 1);
						graphics.setColor(timestampColor);
					}
					graphics.drawString(str, timestampX.get(), timestampY);
					timestampX.addAndGet(cellWidth);
				}

				// Keep every token at its maximum reserved width. A one-digit H/M/d token
				// therefore occupies the same slot as its two-digit form, so separators and all
				// following chat widgets stay at one deterministic X position.
				int reservedChars = segment.endIndex - segment.startIndex;
				int remainingCells = Math.max(0, reservedChars - value.length());
				timestampX.addAndGet(remainingCells * cellWidth);
			}

			@Override
			public void consumeText(String text, int startIndex, int endIndex)
			{
				if (isChatboxTransparent)
				{
					// Draw shadow
					graphics.setColor(Color.BLACK);
					graphics.drawString(text, timestampX.get() + 1, timestampY + 1);
					graphics.setColor(timestampColor);
				}
				graphics.drawString(text, timestampX.get(), timestampY);
				timestampX.addAndGet(graphics.getFontMetrics().stringWidth(text));
			}
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(TimestampConfig.GROUP) && event.getKey().equals("format"))
		{
			updateTemplate();
		}
	}

	public void startUp()
	{
		updateTemplate();
	}

	private void updateTemplate()
	{
		TimestampConfig timestampConfig = timestampConfig();
		FormatterExtractor.ExtractionResult newTemplate = FormatterExtractor.createFromFormatString(timestampConfig.timestampFormat());

		plugin.setTimestampTemplateWidth(0);
		plugin.setTimestampTemplate(newTemplate);

		if (newTemplate != null) {
			FormatterExtractor.iterateOutputParts(newTemplate, new FormatterExtractor.OutputPartConsumer()
			{
				@Override
				public void consumeSegment(FormatterExtractor.FormatSegment segment)
				{
					int reservedChars = segment.endIndex - segment.startIndex;
					plugin.setTimestampTemplateWidth(plugin.getTimestampTemplateWidth()
						+ (cellWidth(segment) * reservedChars));
				}

				@Override
				public void consumeText(String text, int startIndex, int endIndex)
				{
					plugin.setTimestampTemplateWidth(plugin.getTimestampTemplateWidth() + getTextLength(text, client));
				}
			});

			// Native chat spacing is three pixels wide. Align the reserved timestamp slot to
			// that grid so the hidden timestamp replacement and every downstream layout
			// calculation use the exact same pixel width.
			int spaceWidth = Math.max(1, getTextLength(" ", client));
			int rawWidth = plugin.getTimestampTemplateWidth();
			plugin.setTimestampTemplateWidth(((rawWidth + spaceWidth - 1) / spaceWidth) * spaceWidth);
		}

		client.refreshChat();
	}


	private static int cellWidth(FormatterExtractor.FormatSegment segment)
	{
		switch (segment.tokenChar)
		{
			case 'M':
				return segment.tokenCount >= 3 ? TEXT_CELL_WIDTH : NUMERIC_CELL_WIDTH;
			case 'E':
			case 'a':
			case 'z':
				return TEXT_CELL_WIDTH;
			default:
				return NUMERIC_CELL_WIDTH;
		}
	}

	private TimestampConfig timestampConfig()
	{
		return configManager.getConfig(TimestampConfig.class);
	}

	private Color getTimestampColour()
	{
		boolean isChatboxTransparent = client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) == 1;

		TimestampConfig timestampConfig = timestampConfig();
		Color color = isChatboxTransparent ? timestampConfig.transparentTimestamp() : timestampConfig.opaqueTimestamp();

		if (color == null)
		{
			color = isChatboxTransparent ? Color.WHITE : Color.BLACK;
		}

		return color;
	}

}

package com.improvedchat.chatbox.clean.util;

import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.client.util.Text;

public class CleanChatUtil
{
	public static final String CLAN_INSTRUCTION_MESSAGE = "To talk in your clan's channel, start each line of chat with // or /c.";
	public static final int GUEST_CLAN = -1;
	public static final int SCRIPT_REBUILD_CHATBOX = 84;
	// Scripts 32-36 are all about scrolling in different ways
	public static final int SCRIPT_SCROLLBAR_MIN = 32;
	public static final int SCRIPT_SCROLLBAR_MAX = 36;
	public static final int MAX_CHANNEL_LIST_SIZE = 128;
	private static final Pattern IMG_TAG_REGEXP = Pattern.compile("<img=[^>]*>");
	public static final String CURRENT_CLAN_REPLACER = "$$";

	public static String sanitizeName(String string)
	{
		return Text.removeTags(string).replace('\u00A0', ' ');
	}

	// Sizes sourced from: https://github.com/JamesShelton140/aqp-finder
	private static final Map<Character, Integer> CHAR_SIZE_MAP = Map.<Character, Integer>ofEntries(
		// Upper case
		Map.entry('A', 6), Map.entry('B', 5), Map.entry('C', 5), Map.entry('D', 5), Map.entry('E', 4), Map.entry('F', 4), Map.entry('G', 6), Map.entry('H', 5), Map.entry('I', 1), Map.entry('J', 5), Map.entry('K', 5), Map.entry('L', 4), Map.entry('M', 7), Map.entry('N', 6), Map.entry('O', 6), Map.entry('P', 5), Map.entry('Q', 6), Map.entry('R', 5), Map.entry('S', 5), Map.entry('T', 3), Map.entry('U', 6), Map.entry('V', 5), Map.entry('W', 7), Map.entry('X', 5), Map.entry('Y', 5), Map.entry('Z', 5),
		// Lower case
		Map.entry('a', 5), Map.entry('b', 5), Map.entry('c', 4), Map.entry('d', 5), Map.entry('e', 5), Map.entry('f', 4), Map.entry('g', 5), Map.entry('h', 5), Map.entry('i', 1), Map.entry('j', 4), Map.entry('k', 4), Map.entry('l', 1), Map.entry('m', 7), Map.entry('n', 5), Map.entry('o', 5), Map.entry('p', 5), Map.entry('q', 5), Map.entry('r', 3), Map.entry('s', 5), Map.entry('t', 3), Map.entry('u', 5), Map.entry('v', 5), Map.entry('w', 5), Map.entry('x', 5), Map.entry('y', 5), Map.entry('z', 5),
		// Numbers
		Map.entry('0', 6), Map.entry('1', 4), Map.entry('2', 6), Map.entry('3', 5), Map.entry('4', 5), Map.entry('5', 5), Map.entry('6', 6), Map.entry('7', 5), Map.entry('8', 6), Map.entry('9', 6),
		// Symbols
		Map.entry(' ', 1), Map.entry(':', 1), Map.entry(';', 2), Map.entry('"', 3), Map.entry('@', 11), Map.entry('!', 1), Map.entry('.', 1), Map.entry('\'', 2), Map.entry(',', 2), Map.entry('(', 2), Map.entry(')', 2), Map.entry('+', 5), Map.entry('-', 4), Map.entry('=', 6), Map.entry('?', 6), Map.entry('*', 7), Map.entry('/', 4), Map.entry('\\', 4), Map.entry('$', 6), Map.entry('£', 8), Map.entry('^', 6), Map.entry('{', 3), Map.entry('}', 3), Map.entry('[', 3), Map.entry(']', 3), Map.entry('&', 9), Map.entry('#', 11), Map.entry('°', 4), Map.entry('<', 5), Map.entry('>', 5), Map.entry('%', 9), Map.entry('_', 7), Map.entry('|', 1),
		// NBSP
		Map.entry('\u00A0', 1));

	public static int getTextLength(String text, Client client)
	{
		return cleanString(text, client)
			.chars()
			.mapToObj(ch -> (char) ch)
			.map(key -> CHAR_SIZE_MAP.getOrDefault(key, 5) + 2)
			.reduce(0, Integer::sum) + getChatIconsWidth(text);
	}

	private static String cleanString(String s, Client client)
	{
		return Text.unescapeJagex(client.macroExpand(s));
	}

	private static int getChatIconsWidth(String text)
	{
		int imgCount = Math.toIntExact(IMG_TAG_REGEXP.matcher(text).results().count());
		return imgCount * 13; // 11 + 2
	}

	// Mimics 'paraheight' cs2 instruction
	public static int getTextLineCount(String text, int width, int indentSpaces, Client client)
	{
		// Positive lookahead ?= makes it so that the delimiter is included in the split strings
		Iterator<String> iterator = List.of(text.split("(?=<br>|[ \u00A0\n]|<n>)")).iterator();

		int numLines = 0;
		StringBuilder currentLine = new StringBuilder();

		while (iterator.hasNext())
		{
			String next = iterator.next();

			int currentWidth = getTextLength(currentLine.toString(), client);

			if (currentWidth < width)
			{
				// Start of the line
				if (currentLine.toString().isEmpty())
				{
					currentLine.append(next);
				}
				// Adding a line break
				else if (next.startsWith("<br>") || next.startsWith("<n>") || next.charAt(0) == '\n')
				{
					numLines++;
					currentLine = new StringBuilder(next);
				}
				// Adding the next chunk
				else if (currentWidth + getTextLength(next, client) <= width)
				{
					currentLine.append(next);
				}
				// Adding the next chunk after the initial indent
				// `currentWidth + getTextLength(next) > width` is implied
				// add 1 to indentSpaces so that we include the next chunk after the indent on the first line
				else if (numLines == 0 && currentLine.length() <= indentSpaces + 1)
				{
					currentLine.append(next);
				}
				// Width too big, go to next line
				else
				{
					numLines++;
					currentLine = new StringBuilder(next);
				}
			}
			// Width immediately too big, go to next line (this is probably a chunk that will get cut off)
			else
			{
				numLines++;
				currentLine = new StringBuilder(next);
			}
		}
		numLines++;

		return numLines;
	}

	public static String wrapWithBrackets(String channelName)
	{
		return "[" + channelName + "]";
	}

	public static String wrapWithChannelNameRegex(String channelName)
	{
		return "\\[[^]\\[]*" + channelName + ".*]";
	}

}

package com.improvedchat.chatbox.clean.util;

import static com.improvedchat.chatbox.clean.util.SimpleDateFormatUtil.formatTokenToRegex;
import static com.improvedchat.chatbox.clean.util.SimpleDateFormatUtil.getExpandedSize;
import static com.improvedchat.chatbox.clean.util.SimpleDateFormatUtil.isFormatChar;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class FormatterExtractor {

	/**
	 * Represents a segment of the formatted output and its source format token
	 */
	@Value
	public static class FormatSegment
	{
		public String token;      // The format token (e.g., "yyyy", "MM", "dd")
		public char tokenChar;    // The token character (e.g., 'y', 'M', 'd')
		public int tokenCount;    // The number of repetitions (e.g., 4 for "yyyy")
		public int startIndex;    // Start position in the output string
		public int endIndex;      // End position in the output string (exclusive)
		public String value;      // Placeholder value until matched against actual output
	}

	/**
	 * Result containing the formatted output structure and segment information
	 */
	@Value
	public static class ExtractionResult
	{
		String formattedOutput;  // The template output with placeholders
		List<FormatSegment> segments;
		String remainingText;
	}

	/**
	 * Create an ExtractionResult from just the format string.
	 * This expands format characters to their maximum sizes and creates the template.
	 */
	public static ExtractionResult createFromFormatString(String formatString)
	{
		if (!SimpleDateFormatUtil.isValidPattern(formatString)) {
			return null;
		}

		List<FormatSegment> segments = new ArrayList<>();
		StringBuilder templateOutput = new StringBuilder();
		int currentPos = 0;
		int i = 0;

		while (i < formatString.length())
		{
			char c = formatString.charAt(i);

			// Handle quoted literals
			if (c == '\'')
			{
				i++;
				while (i < formatString.length() && formatString.charAt(i) != '\'')
				{
					templateOutput.append(formatString.charAt(i));
					currentPos++;
					i++;
				}
				i++; // Skip closing quote
				continue;
			}

			// Check if this is a format character
			if (isFormatChar(c))
			{
				// Count consecutive identical format characters
				int count = 1;
				while (i + count < formatString.length() && formatString.charAt(i + count) == c)
				{
					count++;
				}

				String token = String.valueOf(c).repeat(count);
				int expandedSize = getExpandedSize(c, count);

				// Create placeholder in template (spaces for now)
				String placeholder = " ".repeat(expandedSize);
				int startIndex = currentPos;
				int endIndex = currentPos + expandedSize;

				templateOutput.append(placeholder);
				segments.add(new FormatSegment(token, c, count, startIndex, endIndex, null));

				currentPos = endIndex;
				i += count;
			}
			else
			{
				// This is a literal character, not a format token
				templateOutput.append(c);
				currentPos++;
				i++;
			}
		}

		return new ExtractionResult(templateOutput.toString(), segments, "");
	}

	/**
	 * Extract the actual formatted output from text using the ExtractionResult template,
	 * and populate the segment values.
	 * This version handles color formatting tags like <col=000000>text</col>
	 */
	public static ExtractionResult extractFromText(ExtractionResult template, String text)
	{
		// Remove color formatting tags for matching purposes
		String cleanedText = removeColorTags(text);

		String regex = formatToRegexFromSegments(template.segments, template.formattedOutput);

		Pattern pattern = Pattern.compile("^" + regex);
		Matcher matcher = pattern.matcher(cleanedText);

		if (matcher.find())
		{
			String formattedOutput = matcher.group(0);
			int matchedLength = formattedOutput.length();

			// Find where the match ends in the original text (accounting for tags)
			int originalEndPos = findOriginalPosition(text, matchedLength);

			// Ensure we don't go past the end of the string
			if (originalEndPos > text.length())
			{
				originalEndPos = text.length();
			}

			String remainingText = originalEndPos < text.length() ?
				text.substring(originalEndPos) : "";

			// Populate segment values from the regex capture groups instead of slicing by the
			// template's maximum-width positions. Variable-width tokens such as H, M, d, or E can
			// produce fewer characters than their reserved template width; slicing by template
			// offsets causes separators/neighboring tokens to leak into the value.
			List<FormatSegment> populatedSegments = new ArrayList<>();
			for (int i = 0; i < template.segments.size(); i++)
			{
				FormatSegment seg = template.segments.get(i);
				String value = matcher.group(i + 1);
				populatedSegments.add(new FormatSegment(seg.token, seg.tokenChar, seg.tokenCount,
					seg.startIndex, seg.endIndex, value));
			}

			return new ExtractionResult(formattedOutput, populatedSegments, remainingText);
		}

		return null;
	}

	/**
	 * Find the position in the original text corresponding to a cleaned text position
	 */
	private static int findOriginalPosition(String originalText, int cleanedPosition)
	{
		int cleanedCount = 0;
		int originalPos = 0;

		while (originalPos < originalText.length() && cleanedCount < cleanedPosition)
		{
			// Check if we're at the start of a color tag
			if (originalText.startsWith("<col=", originalPos))
			{
				// Skip the opening tag
				int closeTag = originalText.indexOf(">", originalPos);
				if (closeTag != -1)
				{
					originalPos = closeTag + 1;
					continue;
				}
			}

			// Check if we're at a closing tag
			if (originalText.startsWith("</col>", originalPos))
			{
				originalPos += 6;
				continue;
			}

			// Regular character
			cleanedCount++;
			originalPos++;
		}

		return originalPos;
	}

	/**
	 * Remove color formatting tags like <col=000000>text</col> from the text
	 */
	private static String removeColorTags(String text)
	{
		// Pattern to match <col=XXXXXX> and </col> tags
		return text.replaceAll("<col=[0-9a-fA-F]{6,8}>|</col>", "");
	}

	/**
	 * Build regex from the segment list and the template (for extracting from actual text)
	 */
	private static String formatToRegexFromSegments(List<FormatSegment> segments, String template)
	{
		StringBuilder regex = new StringBuilder();
		int templatePos = 0;

		for (FormatSegment seg : segments)
		{
			// Add any literal text before this segment
			if (templatePos < seg.startIndex)
			{
				String literal = template.substring(templatePos, seg.startIndex);
				regex.append(Pattern.quote(literal));
			}

			// Add the regex pattern for this segment
			String regexPart = formatTokenToRegex(seg.tokenChar, seg.tokenCount);
			regex.append("(").append(regexPart).append(")");

			templatePos = seg.endIndex;
		}

		// Add any remaining literal text after the last segment
		if (templatePos < template.length())
		{
			String literal = template.substring(templatePos);
			regex.append(Pattern.quote(literal));
		}

		return regex.toString();
	}

	/**
	 * Callback interface for processing each part of the output
	 */
	public interface OutputPartConsumer
	{
		void consumeSegment(FormatSegment segment);

		void consumeText(String text, int startIndex, int endIndex);
	}

	/**
	 * Iterate through the formatted output, calling the consumer for each segment
	 * (format token) or literal text portion.
	 */
	public static void iterateOutputParts(ExtractionResult result, OutputPartConsumer consumer)
	{
		List<FormatSegment> segments = result.segments;
		String output = result.formattedOutput;

		int currentPos = 0;

		for (FormatSegment segment : segments)
		{

			// If there's text before this segment, process it as literal text
			if (currentPos < segment.startIndex)
			{
				String literalText = output.substring(currentPos, segment.startIndex);
				consumer.consumeText(literalText, 0, literalText.length());
				currentPos = segment.startIndex;
			}

			// Process the segment
			consumer.consumeSegment(segment);
			currentPos = segment.endIndex;
		}

		// Process any remaining text after the last segment
		if (currentPos < output.length())
		{
			String remainingText = output.substring(currentPos);
			consumer.consumeText(remainingText, 0, remainingText.length());
		}
	}
}

package com.improvedchat.chatbox.clean.util;

import java.text.SimpleDateFormat;

public class SimpleDateFormatUtil
{

	// TODO: This technically should just be all chars a-z I think?
	/**
	 * Determine if a character is a valid SimpleDateFormat format character
	 */
	static boolean isFormatChar(char c)
	{
		return c == 'y' || c == 'Y' ||
			c == 'M' ||
			c == 'w' || c == 'W' ||
			c == 'd' || c == 'D' ||
			c == 'F' ||
			c == 'E' ||
			c == 'u' ||
			c == 'a' ||
			c == 'H' || c == 'h' ||
			c == 'K' || c == 'k' ||
			c == 'm' ||
			c == 's' || c == 'S' ||
			c == 'z' || c == 'Z' ||
			c == 'X';
	}

	/**
	 * Convert a single format token to regex
	 */
	static String formatTokenToRegex(char token, int count)
	{
		switch (token)
		{
			case 'y': // Year
			case 'Y': // Week-based year
				if (count == 2)
				{
					return "\\d{2}";
				}
				else
				{
					return "\\d{4}";
				}

			case 'M': // Month
				if (count == 1)
				{
					return "\\d{1,2}";
				}
				if (count == 2)
				{
					return "\\d{2}";
				}
				if (count == 3)
				{
					return "[A-Z][a-z]{2}";
				}
				return "[A-Z][a-z]+";

			case 'w': // Week of year
				if (count == 1)
				{
					return "\\d{1,2}";
				}
				return "\\d{2}";

			case 'W': // Week of month
				return "\\d";

			case 'd': // Day of month
				if (count == 1)
				{
					return "\\d{1,2}";
				}
				return "\\d{2}";

			case 'D': // Day of year
				if (count == 1)
				{
					return "\\d{1,3}";
				}
				if (count == 2)
				{
					return "\\d{1,3}";
				}
				return "\\d{3}";

			case 'F': // Day of week in month
				return "\\d";

			case 'E': // Day name
				if (count < 4)
				{
					return "[A-Z][a-z]{2}";
				}
				return "[A-Z][a-z]+";

			case 'u': // Day of week (1-7, Monday = 1)
				return "\\d";

			case 'a': // AM/PM
				return "AM|PM";

			case 'H': // Hour (0-23)
				if (count == 1)
				{
					return "\\d{1,2}";
				}
				return "\\d{2}";

			case 'h': // Hour (1-12)
				if (count == 1)
				{
					return "\\d{1,2}";
				}
				return "\\d{2}";

			case 'K': // Hour (0-11)
			case 'k': // Hour (1-24)
				if (count == 1)
				{
					return "\\d{1,2}";
				}
				return "\\d{2}";

			case 'm': // Minute
			case 's': // Second
				if (count == 1)
				{
					return "\\d{1,2}";
				}
				return "\\d{2}";


			case 'S': // Millisecond/Nanosecond
				return "\\d{" + count + "}";

			case 'z': // Time zone abbreviation
				return "[A-Z]{3,4}";

			case 'Z': // Time zone offset
				return "[+-]\\d{4}";

			case 'X': // ISO time zone (±HH:mm, ±HHMM, or Z)
				if (count == 1)
				{
					return "[+-]\\d{2}|Z";
				}
				if (count == 2)
				{
					return "[+-]\\d{2}:\\d{2}|Z";
				}
				return "[+-]\\d{2}:\\d{2}:\\d{2}|Z";

			default:
				return ".{1," + count + "}";
		}
	}

	/**
	 * Get the maximum expanded size for a format token
	 */
	static int getExpandedSize(char token, int count)
	{
		switch (token)
		{
			case 'y': // Year
				return count == 2 ? 2 : 4;
			case 'Y': // Week-based year
				return 4;
			case 'M': // Month
				if (count == 1 || count == 2)
					return 2;
				if (count == 3)
					return 3;
				return 9; // "September"
			case 'w': // Week of year
				return 2;
			case 'W': // Week of month
				return 1;
			case 'd': // Day of month
				return 2;
			case 'D': // Day of year
				return 3;
			case 'F': // Day of week in month
				return 1;
			case 'E': // Day name
				return count < 4 ? 3 : 9; // "Mon" or "Monday"
			case 'u': // Day of week (1-7)
				return 1;
			case 'a': // AM/PM
				return 2;
			case 'H': // Hour (0-23)
				return 2;
			case 'h': // Hour (1-12)
				return 2;
			case 'K': // Hour (0-11)
				return 2;
			case 'k': // Hour (1-24)
				return 2;
			case 'm': // Minute
				return 2;
			case 's': // Second
				return 2;
			case 'S': // Millisecond
				return count;
			case 'z': // Time zone
				return 4; // "EST" TODO EST is 3 letters?
			case 'Z': // Time zone offset
				return 5; // "+0000"
			case 'X': // ISO time zone
				return 6; // "+00:00"
			default:
				return count;
		}
	}

	public static boolean isValidPattern(String pattern)
	{
		if (pattern == null)
		{
			return false;
		}

		try
		{
			new SimpleDateFormat(pattern);
			return true;
		}
		catch (IllegalArgumentException e)
		{
			return false;
		}
	}
}

