 *
 * Rank icons are resolved through RuneLite's ChatIconManager. The offline marker is also registered
 * through ChatIconManager so it survives mod-icon array rebuilds performed by RuneLite or another
 * plugin. Online state is deliberately reported as unknown while the relevant clan channel is not
 * available, avoiding false "offline" markers during login/world-hop reconnects.
 */
@Singleton
public final class ClanChatPresentationService
{
    private static final int NO_ICON = -1;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private ChatIconManager chatIconManager;

    private final Map<String, Integer> rankIconCache = new ConcurrentHashMap<>();
    private boolean started;
    private int offlineIconHandle = NO_ICON;

    public synchronized void startUp()
    {
        if (started)
        {
            return;
        }

        started = true;
        eventBus.register(this);
        clientThread.invokeLater(() ->
        {
            ensureOfflineIconRegistered();
            cacheOnlineRanks();
        });
    }

    public synchronized void shutDown()
    {
        if (!started)
        {
            return;
        }

        started = false;
        eventBus.unregister(this);
        rankIconCache.clear();
    }

    public Presentation resolve(String sender, ChatMessageType type)
    {
        ClanContext context = contextFor(type);
        if (context == null || sender == null || sender.isEmpty())
        {
            return Presentation.notClan();
        }

        String cleanName = Text.removeTags(sender).trim();
        if (cleanName.isEmpty())
        {
            return Presentation.notClan();
        }

        ClanChannel channel = context.channel();
        ClanSettings settings = context.settings();
        ClanChannelMember member = channel == null ? null : channel.findMember(cleanName);

        int rankIcon = cachedRankIcon(context.cachePrefix, cleanName);
        if (member != null)
        {
            int resolved = resolveRankIcon(member, settings);
            if (resolved >= 0)
            {
                rankIcon = resolved;
                rankIconCache.put(cacheKey(context.cachePrefix, cleanName), resolved);
            }
        }

        boolean statusKnown = channel != null;
        boolean offline = statusKnown && member == null;
        return new Presentation(true, statusKnown, offline, rankIcon, getOfflineIconIndex());
    }

    public int getOfflineIconIndex()
    {
        if (offlineIconHandle < 0)
        {
            return NO_ICON;
        }
        return chatIconManager.chatIconIndex(offlineIconHandle);
    }

    @Subscribe
    public void onClanMemberJoined(ClanMemberJoined event)
    {
        cacheMember(event.getClanChannel(), event.getClanMember());
    }

    @Subscribe
    public void onClanMemberLeft(ClanMemberLeft event)
    {
        // The event still has the member rank, so retain the icon for messages after they leave.
        cacheMember(event.getClanChannel(), event.getClanMember());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(this::cacheOnlineRanks);
        }
    }

    private void ensureOfflineIconRegistered()
    {
        if (offlineIconHandle >= 0)
        {
            return;
        }
        offlineIconHandle = chatIconManager.registerChatIcon(createOfflineIconImage());
    }

    private void cacheOnlineRanks()
    {
        cacheChannel("clan", client.getClanChannel(), client.getClanSettings());
        cacheChannel("guest", client.getGuestClanChannel(), client.getGuestClanSettings());
        cacheChannel("gim", client.getClanChannel(ClanID.GROUP_IRONMAN),
            client.getClanSettings(ClanID.GROUP_IRONMAN));
    }

    private void cacheChannel(String prefix, ClanChannel channel, ClanSettings settings)
    {
        if (channel == null || settings == null)
        {
            return;
        }

        for (ClanChannelMember member : channel.getMembers())
        {
            int icon = resolveRankIcon(member, settings);
            if (icon >= 0)
            {
                rankIconCache.put(cacheKey(prefix, member.getName()), icon);
            }
        }
    }

    private void cacheMember(ClanChannel channel, ClanChannelMember member)
    {
        if (channel == null || member == null)
        {
            return;
        }

        String prefix;
        ClanSettings settings;
        if (channel == client.getClanChannel())
        {
            prefix = "clan";
            settings = client.getClanSettings();
        }
        else if (channel == client.getGuestClanChannel())
        {
            prefix = "guest";
            settings = client.getGuestClanSettings();
        }
        else if (channel == client.getClanChannel(ClanID.GROUP_IRONMAN))
        {
            prefix = "gim";
            settings = client.getClanSettings(ClanID.GROUP_IRONMAN);
        }
        else
        {
            return;
        }

        int icon = resolveRankIcon(member, settings);
        if (icon >= 0)
        {
            rankIconCache.put(cacheKey(prefix, member.getName()), icon);
        }
    }

    private int resolveRankIcon(ClanChannelMember member, ClanSettings settings)
    {
        if (member == null || settings == null || member.getRank() == null)
        {
            return NO_ICON;
        }

        ClanTitle title = settings.titleForRank(member.getRank());
        return title == null ? NO_ICON : chatIconManager.getIconNumber(title);
    }

    private int cachedRankIcon(String prefix, String name)
    {
        Integer icon = rankIconCache.get(cacheKey(prefix, name));
        return icon == null ? NO_ICON : icon;
    }

    private static String cacheKey(String prefix, String name)
    {
        return prefix + ":" + Text.standardize(Text.removeTags(name == null ? "" : name));
    }

    private ClanContext contextFor(ChatMessageType type)
    {
        if (type == ChatMessageType.CLAN_CHAT)
        {
            return new ClanContext("clan", client.getClanChannel(), client.getClanSettings());
        }
        if (type == ChatMessageType.CLAN_GUEST_CHAT)
        {
            return new ClanContext("guest", client.getGuestClanChannel(), client.getGuestClanSettings());
        }
        if (type == ChatMessageType.CLAN_GIM_CHAT)
        {
            return new ClanContext("gim", client.getClanChannel(ClanID.GROUP_IRONMAN),
                client.getClanSettings(ClanID.GROUP_IRONMAN));
        }
        return null;
    }

    static BufferedImage createOfflineIconImage()
    {
        BufferedImage image = new BufferedImage(11, 11, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            // ImageUtil.getImageIndexedSprite only keeps fully opaque pixels. Do not antialias this
            // marker or its partially-transparent edge pixels will disappear from the indexed sprite.
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            graphics.setColor(new Color(150, 150, 150, 255));
            graphics.setStroke(new BasicStroke(1f));
            graphics.drawOval(1, 1, 8, 8);
            graphics.drawLine(3, 3, 8, 8);
        }
        finally
        {
            graphics.dispose();
        }
        return image;
    }

    private static final class ClanContext
    {
        private final String cachePrefix;
        private final ClanChannel channel;
        private final ClanSettings settings;

        private ClanContext(String cachePrefix, ClanChannel channel, ClanSettings settings)
        {
            this.cachePrefix = cachePrefix;
            this.channel = channel;
            this.settings = settings;
        }

        private ClanChannel channel()
        {
            return channel;
        }

        private ClanSettings settings()
        {
            return settings;
        }
    }

    public static final class Presentation
    {
        private final boolean clanMessage;
        private final boolean statusKnown;
        private final boolean offline;
        private final int rankIconId;
        private final int offlineIconId;

        private Presentation(boolean clanMessage, boolean statusKnown, boolean offline,
            int rankIconId, int offlineIconId)
        {
            this.clanMessage = clanMessage;
            this.statusKnown = statusKnown;
            this.offline = offline;
            this.rankIconId = rankIconId;
            this.offlineIconId = offlineIconId;
        }

        private static Presentation notClan()
        {
            return new Presentation(false, false, false, NO_ICON, NO_ICON);
        }

        public boolean isClanMessage()
        {
            return clanMessage;
        }

        public boolean isStatusKnown()
        {
            return statusKnown;
        }

        public boolean isOffline()
        {
            return offline;
        }

        public int getRankIconId()
        {
            return rankIconId;
        }

        public int getOfflineIconId()
        {
            return offlineIconId;
        }
    }
}

package com.improvedchat.chatbox.offline;

import com.improvedchat.model.MessageNodeIdentity;
import java.util.Objects;
import net.runelite.api.MessageNode;

/**
 * Tracks the unmodified sender name for one logical clan chat message.
 *
 * MessageNode objects can be recycled. The identity snapshot prevents a name saved for an older
 * message from ever being written onto a newer message which happens to reuse the same node object.
 */
final class ClanNameState
{
    private final MessageNodeIdentity identity;
    private String originalName;
    private String lastAppliedName;

    private ClanNameState(MessageNodeIdentity identity, String originalName)
    {
        this.identity = identity;
        this.originalName = normalize(originalName);
        this.lastAppliedName = this.originalName;
    }

    static ClanNameState capture(MessageNode node)
    {
        return new ClanNameState(MessageNodeIdentity.capture(node), node == null ? "" : node.getName());
    }

    boolean matches(MessageNode node)
    {
        return identity != null && identity.matches(node);
    }

    String baseName(String currentName)
    {
        String current = normalize(currentName);

        // Respect another plugin changing the name on the same logical message. Treat its new value
        // as the baseline rather than restoring our older copy over it.
        if (!Objects.equals(current, lastAppliedName) && !Objects.equals(current, originalName))
        {
            originalName = current;
            lastAppliedName = current;
        }

        return originalName;
    }

    void recordApplied(String value)
    {
        lastAppliedName = normalize(value);
    }

    boolean shouldRestore(MessageNode node)
    {
        return matches(node)
            && Objects.equals(normalize(node.getName()), lastAppliedName)
            && !Objects.equals(originalName, lastAppliedName);
    }

    String getOriginalName()
    {
        return originalName;
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value;
    }
}

package com.improvedchat.chatbox.offline;

import com.improvedchat.ImprovedChatConfig;
import java.awt.Color;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.IterableHashTable;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ClanMemberJoined;
import net.runelite.api.events.ClanMemberLeft;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

/**
 * Native-chat offline clan presentation. Icon registration/status resolution are shared with
 * Improved Chat overlays through {@link ClanChatPresentationService}.
 */
@Singleton
public final class OfflineChatStatusModule
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ImprovedChatConfig config;
    @Inject private EventBus eventBus;
    @Inject private ClanChatPresentationService clanPresentation;

    private final Map<MessageNode, ClanNameState> nameStates = new IdentityHashMap<>();
    private boolean started;

    public synchronized void startUp()
    {
        if (started || !config.enableOfflineChatStatus())
        {
            return;
        }

        started = true;
        eventBus.register(this);

        // ChatIconManager assigns registered icon indices asynchronously. Two deferred passes let
        // the shared offline marker finish registration before names are rebuilt.
        clientThread.invokeLater(() -> clientThread.invokeLater(this::formatAll));
    }

    public synchronized void shutDown()
    {
        if (!started)
        {
            return;
        }

        started = false;
        eventBus.unregister(this);
        clientThread.invoke(this::restoreAll);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!ImprovedChatConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }

        if ("enableOfflineIcon".equals(event.getKey())
            || "enableOfflineColor".equals(event.getKey())
            || "offlineColor".equals(event.getKey()))
        {
            clientThread.invokeLater(this::formatAll);
        }
    }

    @Subscribe
    public void onClanMemberJoined(ClanMemberJoined event)
    {
        clientThread.invokeLater(this::formatAll);
    }

    @Subscribe
    public void onClanMemberLeft(ClanMemberLeft event)
    {
        clientThread.invokeLater(this::formatAll);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(() -> clientThread.invokeLater(this::formatAll));
        }
    }

    private void formatAll()
    {
        if (!started)
        {
            return;
        }

        IterableHashTable<MessageNode> messages = client.getMessages();
        if (messages == null)
        {
            return;
        }

        boolean changed = false;
        Set<MessageNode> liveNodes = Collections.newSetFromMap(new IdentityHashMap<>());
        for (MessageNode message : messages)
        {
            liveNodes.add(message);
            changed |= format(message);
        }

        // Do not retain strong references to chat nodes that have left RuneLite's active message
        // table. This also prevents stale decoration state from surviving longer than the message.
        nameStates.keySet().removeIf(node -> !liveNodes.contains(node));

        if (changed)
        {
            client.refreshChat();
        }
    }

    private boolean format(MessageNode message)
    {
        ChatMessageType type = message.getType();
        if (type != ChatMessageType.CLAN_CHAT
            && type != ChatMessageType.CLAN_GUEST_CHAT
            && type != ChatMessageType.CLAN_GIM_CHAT)
        {
            return false;
        }

        String currentName = message.getName();
        ClanNameState state = nameStates.get(message);
        if (state == null || !state.matches(message))
        {
            // RuneLite recycles MessageNode objects as the chat buffer advances. A recycled node
            // must start with the new message's own sender name, never the cached name from the
            // older message which previously occupied this object.
            state = ClanNameState.capture(message);
            nameStates.put(message, state);
        }

        String base = state.baseName(currentName);

        ClanChatPresentationService.Presentation presentation =
            clanPresentation.resolve(base, type);

        String result = base;
        if (presentation.isOffline())
        {
            if (config.enableOfflineColor())
            {
                Color color = config.offlineColor();
                result = String.format("<col=%02x%02x%02x>%s</col>",
                    color.getRed(), color.getGreen(), color.getBlue(), result);
            }

            if (config.enableOfflineIcon() && presentation.getOfflineIconId() >= 0)
            {
                result = "<img=" + presentation.getOfflineIconId() + ">" + result;
            }
        }

        boolean changed = !result.equals(currentName);
        if (changed)
        {
            message.setName(result);
        }
        state.recordApplied(result);
        return changed;
    }

    private void restoreAll()
    {
        boolean changed = false;
        for (Map.Entry<MessageNode, ClanNameState> entry : nameStates.entrySet())
        {
            try
            {
                MessageNode node = entry.getKey();
                ClanNameState state = entry.getValue();

                // Never restore onto a recycled node, and never overwrite a name another plugin
                // changed after our last decoration pass.
                if (state.shouldRestore(node))
                {
                    node.setName(state.getOriginalName());
                    changed = true;
                }
            }
            catch (Exception ignored)
            {
                // Message nodes can expire while the plugin is enabled.
            }
        }

        nameStates.clear();
        if (changed)
        {
            client.refreshChat();
        }
    }
}

package com.improvedchat.chatbox.opacity;

import com.improvedchat.ImprovedChatConfig;
import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

/**
 * Improved Chat native chatbox opacity handling for transparent resizable chat.
 */
@Singleton
public final class ChatboxOpacityModule {
    private static final int CHATBOX_GROUP_ID = 162;
    private static final int BUTTON_BACKGROUND_CHILD = 3;
    private static final int ORIGINAL_BUTTON_TYPE = 5;
    private static final int FILLED_BUTTON_TYPE = 3;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ImprovedChatConfig config;
    @Inject private EventBus eventBus;

    private final Map<Widget, Integer> backgroundOpacity = new IdentityHashMap<>();
    private boolean started;
    private boolean deferredApplyQueued;
    private int buttonSprite = -1;
    private int buttonOpacity = -1;
    private boolean buttonFilled;
    private int buttonType = ORIGINAL_BUTTON_TYPE;

    public synchronized void startUp() {
        if (started || !config.enableChatboxOpacity()) return;
        started = true;
        eventBus.register(this);
        clientThread.invoke(this::apply);
    }

    public synchronized void shutDown() {
        if (!started) return;
        started = false;
        deferredApplyQueued = false;
        eventBus.unregister(this);
        clientThread.invoke(() -> {
            restoreBackground();
            restoreButton();
            if (client.getGameState() == GameState.LOGGED_IN) client.runScript(ScriptID.BUILD_CHATBOX);
        });
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == ScriptID.BUILD_CHATBOX) apply();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!ImprovedChatConfig.GROUP.equals(event.getGroup())) return;
        String key = event.getKey();
        if ("chatboxOpacity".equals(key) || "buttonOpacity".equals(key) || "opacityDialogueMenus".equals(key)) {
            clientThread.invokeLater(this::apply);
        }
    }

    public void reapplyAfterChatMutation() {
        if (!started) return;

        apply();

        if (!deferredApplyQueued) {
            deferredApplyQueued = true;
            clientThread.invokeLater(() -> {
                deferredApplyQueued = false;
                apply();
            });
        }
    }

    private void apply() {
        if (!started) return;

        if (client.getGameState() != GameState.LOGGED_IN
            || !client.isResized()
            || client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) == 0) {
            restoreBackground();
            restoreButton();
            return;
        }

        Widget background = client.getWidget(net.runelite.api.gameval.InterfaceID.Chatbox.CHAT_BACKGROUND);
        Widget[] children = background == null ? null : background.getDynamicChildren();
        if (children != null) {
            // Transparent chat normally uses rectangle/gradient children. Dialogue and option menus
            // temporarily replace that surface with the opaque parchment graphic even while the
            // transparent-chat varbit remains enabled. Allow users to keep those surfaces native.
            if (!config.opacityDialogueMenus() && isDialogueOrMenuSurface(children)) {
                restoreBackground();
            } else {
                boolean generationChanged = backgroundOpacity.size() != liveCount(children);
                if (!generationChanged) {
                    for (Widget child : children) {
                        if (child != null && !backgroundOpacity.containsKey(child)) {
                            generationChanged = true;
                            break;
                        }
                    }
                }
                if (generationChanged) {
                    backgroundOpacity.clear();
                    for (Widget child : children) {
                        if (child != null) {
                            backgroundOpacity.put(child, child.getOpacity());
                        }
                    }
                }

                if (config.chatboxOpacity() == -1) {
                    restoreBackground();
                } else {
                    for (Widget child : children) {
                        if (child != null) {
                            child.setOpacity(config.chatboxOpacity());
                        }
                    }
                }
            }
        }

        Widget button = client.getWidget(CHATBOX_GROUP_ID, BUTTON_BACKGROUND_CHILD);
        if (button == null) return;
        if (config.buttonOpacity() == -1) {
            restoreButton();
        } else {
            if (buttonSprite == -1) {
                buttonSprite = button.getSpriteId();
                buttonOpacity = button.getOpacity();
                buttonFilled = button.isFilled();
                buttonType = button.getType();
            }
            button.setSpriteId(-1);
            button.setType(FILLED_BUTTON_TYPE);
            button.setFilled(true);
            button.setOpacity(config.buttonOpacity());
        }
    }

    private static boolean isDialogueOrMenuSurface(Widget[] widgets) {
        for (Widget widget : widgets) {
            if (widget != null) {
                return widget.getType() == WidgetType.GRAPHIC;
            }
        }
        return false;
    }

    private static int liveCount(Widget[] widgets) {
        int count = 0;
        for (Widget widget : widgets) if (widget != null) count++;
        return count;
    }

    private void restoreBackground() {
        for (Map.Entry<Widget, Integer> entry : backgroundOpacity.entrySet()) {
            try {
                entry.getKey().setOpacity(entry.getValue());
            } catch (Exception ignored) {
                // Widget generations are transient; stale instances can safely be dropped.
            }
        }
        backgroundOpacity.clear();
    }

    private void restoreButton() {
        if (buttonSprite == -1) return;
        Widget button = client.getWidget(CHATBOX_GROUP_ID, BUTTON_BACKGROUND_CHILD);
        if (button != null) {
            button.setSpriteId(buttonSprite);
            button.setOpacity(buttonOpacity);
            button.setFilled(buttonFilled);
            button.setType(buttonType);
        }
        buttonSprite = -1;
        buttonOpacity = -1;
    }
}

