package com.improvedchat.model;

import java.util.regex.Pattern;

public final class MessageMergeRule {
    private final String previousPrefix;
    private final String nextPattern;
    private final boolean exactMatch;
    private final Pattern regexPattern;

    public MessageMergeRule(String previousPrefix, String nextPattern, boolean exactMatch) {
        this.previousPrefix = previousPrefix;
        this.nextPattern = nextPattern;
        this.exactMatch = exactMatch;
        this.regexPattern = null;
    }

    public MessageMergeRule(String previousPrefix, Pattern regexPattern) {
        this.previousPrefix = previousPrefix;
        this.nextPattern = null;
        this.exactMatch = false;
        this.regexPattern = regexPattern;
    }

    public boolean matches(String previous, String next) {
        if (!previous.startsWith(previousPrefix)) {
            return false;
        }
        if (regexPattern != null) {
            return regexPattern.matcher(next).matches();
        }
        return exactMatch ? next.equals(nextPattern) : next.startsWith(nextPattern);
    }

    public String merge(String previous, String next) {
        return previous + " " + next;
    }

    public boolean matchesPreviousPrefix(String message) {
        return message.startsWith(previousPrefix);
    }
}

package com.improvedchat.model;

import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;

/**
 * Stable identity snapshot for a RuneLite chat message node.
 *
 * RuneLite may recycle MessageNode objects as the chat buffer advances. Code which keeps a node
 * reference beyond the current chat event must verify that the node still represents the same
 * logical message before reading from or writing to it.
 */
public final class MessageNodeIdentity
{
    private final int id;
    private final int timestamp;
    private final ChatMessageType type;

    private MessageNodeIdentity(int id, int timestamp, ChatMessageType type)
    {
        this.id = id;
        this.timestamp = timestamp;
        this.type = type;
    }

    public static MessageNodeIdentity capture(MessageNode node)
    {
        if (node == null)
        {
            return null;
        }
        return new MessageNodeIdentity(node.getId(), node.getTimestamp(), node.getType());
    }

    public boolean matches(MessageNode node)
    {
        return node != null
            && node.getId() == id
            && node.getTimestamp() == timestamp
            && node.getType() == type;
    }
}

