        NodeState state = new NodeState(101, 12345, ChatMessageType.CLAN_CHAT, "Alice", "hello");
        MessageNode node = state.proxy();
        MessageNodeIdentity identity = MessageNodeIdentity.capture(node);

        state.timestamp = 12346;
        assertFalse(identity.matches(node));

        state.timestamp = 12345;
        state.type = ChatMessageType.CLAN_GUEST_CHAT;
        assertFalse(identity.matches(node));
    }

    private static final class NodeState
    {
        private int id;
        private int timestamp;
        private ChatMessageType type;
        private String name;
        private String value;

        private NodeState(int id, int timestamp, ChatMessageType type, String name, String value)
        {
            this.id = id;
            this.timestamp = timestamp;
            this.type = type;
            this.name = name;
            this.value = value;
        }

        private MessageNode proxy()
        {
            return (MessageNode) Proxy.newProxyInstance(
                MessageNode.class.getClassLoader(),
                new Class<?>[] {MessageNode.class},
                (proxy, method, args) ->
                {
                    switch (method.getName())
                    {
                        case "getId": return id;
                        case "getTimestamp": return timestamp;
                        case "getType": return type;
                        case "getName": return name;
                        case "setName": name = (String) args[0]; return null;
                        case "getValue": return value;
                        case "setValue": value = (String) args[0]; return null;
                        case "hashCode": return System.identityHashCode(proxy);
                        case "equals": return proxy == args[0];
                        case "toString": return "MessageNodeProxy";
                        default:
                            Class<?> returnType = method.getReturnType();
                            if (returnType == boolean.class) return false;
                            if (returnType == int.class) return 0;
                            if (returnType == long.class) return 0L;
                            return null;
                    }
                });
        }
    }
}

package com.improvedchat.overlay;

import com.improvedchat.model.FontSize;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ChatRenderUtilsTest {
    private static FontMetrics metrics;

    @BeforeClass
    public static void setUp() {
        BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        metrics = graphics.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        graphics.dispose();
    }

    @Test
    public void senderTextDecodesAtEscape() {
        assertEquals("Bob@Home", textOf(ChatRenderUtils.parseTextWithIcons(
                "Bob<at>Home", metrics, null, Color.WHITE, FontSize.REGULAR)));
    }

    @Test
    public void messageTextDecodesRuneLiteEscapes() {
        assertEquals("a@<b>@", textOf(ChatRenderUtils.parseTextWithColoursAndIcons(
                "a<at><lt>b<gt><at>", metrics, null, true, Color.WHITE,
                FontSize.REGULAR, null)));
    }

    private static String textOf(List<TextSegment> segments) {
        StringBuilder text = new StringBuilder();
        for (TextSegment segment : segments) {
            if (segment.iconId == -1) {
                text.append(segment.text);
            }
        }
        return text.toString();
    }
}

package com.improvedchat.overlay;

import com.improvedchat.model.PlacementMode;
import com.improvedchat.model.TextAlignment;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class OverlayAlignmentTest {
    @Test
    public void calculatesLeftCenterAndRightPositions() {
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.LEFT, 4, 100, 40));
        assertEquals(34, DynamicChatOverlay.calculateAlignedX(TextAlignment.CENTER, 4, 100, 40));
        assertEquals(64, DynamicChatOverlay.calculateAlignedX(TextAlignment.RIGHT, 4, 100, 40));
    }

    @Test
    public void clampsAlignmentWhenLineExceedsContentWidth() {
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.LEFT, 4, 100, 140));
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.CENTER, 4, 100, 140));
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.RIGHT, 4, 100, 140));
    }

    @Test
    public void preservesLegacyPlacementDefaultsUntilAlignmentIsExplicitlySet() {
        OverlayConfig config = new OverlayConfig();
        assertEquals(TextAlignment.LEFT, config.getTextAlignment());

        config.setPlacementMode(PlacementMode.ABOVE_PLAYER);
        assertEquals(TextAlignment.CENTER, config.getTextAlignment());

        config.setTextAlignment(TextAlignment.RIGHT);
        config.setPlacementMode(PlacementMode.FREE);
        assertEquals(TextAlignment.RIGHT, config.getTextAlignment());
    }
}

package com.improvedchat.overlay;

import java.awt.Color;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OverlayClanDisplayConfigTest
{
    @Test
    public void clanRankIconsAreShownByDefault()
    {
        OverlayConfig config = new OverlayConfig();
        assertTrue(config.isShowClanRankIcons());
    }

    @Test
    public void offlinePresentationIsOptInPerOverlay()
    {
        OverlayConfig config = new OverlayConfig();

        assertFalse(config.isShowOfflineStatus());
        assertTrue(config.isShowOfflineIcon());
        assertTrue(config.isColorOfflineNames());
        assertEquals(Color.DARK_GRAY, config.getOfflineColor());
    }

    @Test
    public void iconTagDetectionMatchesOnlyTheRequestedIcon()
    {
        String sender = "<img=17><img=42>Alice";

        assertTrue(DynamicChatOverlay.containsIconTag(sender, 17));
        assertTrue(DynamicChatOverlay.containsIconTag(sender, 42));
        assertFalse(DynamicChatOverlay.containsIconTag(sender, 9));
        assertFalse(DynamicChatOverlay.containsIconTag(null, 17));
        assertFalse(DynamicChatOverlay.containsIconTag(sender, -1));
    }

    @Test
    public void offlineIconDoesNotSuppressDifferentClanRankIcon()
    {
        String senderAlreadyContainingOfflineMarker = "<img=42>Alice";

        assertTrue(DynamicChatOverlay.containsIconTag(senderAlreadyContainingOfflineMarker, 42));
        assertFalse(DynamicChatOverlay.containsIconTag(senderAlreadyContainingOfflineMarker, 17));
    }

    @Test
    public void overlayOfflineSettingsAreIndependent()
    {
        OverlayConfig first = new OverlayConfig();
        OverlayConfig second = new OverlayConfig();

        first.setShowOfflineStatus(true);
        first.setShowOfflineIcon(false);
        first.setColorOfflineNames(true);
        first.setOfflineColor(Color.GRAY);

        assertTrue(first.isShowOfflineStatus());
        assertFalse(first.isShowOfflineIcon());
        assertEquals(Color.GRAY, first.getOfflineColor());

        assertFalse(second.isShowOfflineStatus());
        assertTrue(second.isShowOfflineIcon());
        assertEquals(Color.DARK_GRAY, second.getOfflineColor());
    }
}

package com.improvedchat.overlay;

import com.improvedchat.ImprovedChatConfig;
import com.improvedchat.model.OverlayMessage;
import net.runelite.api.ChatMessageType;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OverlayMessageFilterTest
{
    @Test
    public void newOverlayDefaultsDoNotChangeExistingBehavior()
    {
        OverlayConfig config = new OverlayConfig();
        assertFalse(config.isUseGlobalChatFilter());
        assertEquals(OverlayFilterMode.OFF, config.getFilterMode());
        assertEquals("", config.getFilteredWords());
        assertEquals("", config.getFilteredRegex());
        assertEquals("", config.getFilteredNames());
    }

    @Test
    public void globalOverrideTakesPrecedence()
    {
        OverlayConfig config = new OverlayConfig();
        assertFalse(OverlayMessageFilter.usesGlobalChatFilter(false, config));

        config.setUseGlobalChatFilter(true);
        assertTrue(OverlayMessageFilter.usesGlobalChatFilter(false, config));

        config.setUseGlobalChatFilter(false);
        assertTrue(OverlayMessageFilter.usesGlobalChatFilter(true, config));
    }

    @Test
    public void hideMatchesSupportsWordsAndRegex()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.HIDE_MATCHES);
        config.setFilteredWords("buy gold, spam phrase");
        config.setFilteredRegex("^You have .* coins$");

        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.gameMessage("BUY GOLD now", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.gameMessage("You have 42 coins", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertFalse(filter.shouldExclude(config,
            OverlayMessage.gameMessage("A normal message", 0, ChatMessageType.GAMEMESSAGE, false)));
    }

    @Test
    public void showOnlyMatchesInvertsTheDecision()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.SHOW_ONLY_MATCHES);
        config.setFilteredWords("collection log");

        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertFalse(filter.shouldExclude(config,
            OverlayMessage.gameMessage("Collection log updated", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.gameMessage("You eat the shark.", 0, ChatMessageType.GAMEMESSAGE, false)));
    }

    @Test
    public void senderRulesSupportLiteralAndRegexEntries()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.HIDE_MATCHES);
        config.setFilteredNames("Alice\nregex:^Bob[0-9]+$");

        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.senderMessage("Alice", null, "hello", 0, ChatMessageType.PUBLICCHAT, false)));
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.senderMessage("Bob42", null, "hello", 0, ChatMessageType.PUBLICCHAT, false)));
        assertFalse(filter.shouldExclude(config,
            OverlayMessage.senderMessage("Charlie", null, "hello", 0, ChatMessageType.PUBLICCHAT, false)));
    }

    @Test
    public void invalidRegexIsIgnoredWithoutBreakingFiltering()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.HIDE_MATCHES);
        config.setFilteredWords("valid");
        config.setFilteredRegex("[invalid");

        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.gameMessage("valid message", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertFalse(filter.shouldExclude(config,
            OverlayMessage.gameMessage("other message", 0, ChatMessageType.GAMEMESSAGE, false)));
    }

    @Test
    public void globalConfigKeepsExistingKeyButUsesNewLabel() throws Exception
    {
        ConfigItem item = ImprovedChatConfig.class.getMethod("useChatFilter").getAnnotation(ConfigItem.class);
        assertEquals("useChatFilter", item.keyName());
        assertEquals("Use Chat Filter Globally", item.name());
        assertEquals(
            "When enabled, overrides all overlay chat filters with the RuneLite global chat filter",
            item.description());
    }
}

package com.improvedchat.release;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ReleaseNoticeModuleTest
{
    @Test
    public void newReleaseStartsAtReminderOne()
    {
        assertEquals(1, ReleaseNoticeModule.nextReminderIndex(null, null));
        assertEquals(1, ReleaseNoticeModule.nextReminderIndex("older-release", "2"));
    }

    @Test
    public void currentReleaseAdvancesExactlyTwice()
    {
        String id = ReleaseNoticeModule.CURRENT_NOTICE_ID;

        assertEquals(1, ReleaseNoticeModule.nextReminderIndex(id, null));
        assertEquals(1, ReleaseNoticeModule.nextReminderIndex(id, "0"));
        assertEquals(2, ReleaseNoticeModule.nextReminderIndex(id, "1"));
        assertEquals(0, ReleaseNoticeModule.nextReminderIndex(id, "2"));
        assertEquals(0, ReleaseNoticeModule.nextReminderIndex(id, "3"));
    }

    @Test
    public void malformedStoredCountRecoversAtReminderOne()
    {
        String id = ReleaseNoticeModule.CURRENT_NOTICE_ID;

        assertEquals(1, ReleaseNoticeModule.nextReminderIndex(id, "not-a-number"));
        assertEquals(1, ReleaseNoticeModule.nextReminderIndex(id, "-5"));
    }

    @Test
    public void messagesUseRequestedReminderLabels()
    {
        String first = ReleaseNoticeModule.buildMessage(1);
        String second = ReleaseNoticeModule.buildMessage(2);

        assertTrue(first.startsWith("Improved Chat has been updated:"));
        assertTrue(first.endsWith("Reminder 1/2"));
        assertTrue(second.endsWith("Reminder 2/2"));
    }
}
